INSERT INTO item_exclusion (
    item_id,
    participant_id
)
SELECT
    i.id,
    p.id
FROM item i
JOIN settle_round r ON r.id = i.round_id
JOIN settlement_participant p ON p.settlement_id = r.settlement_id
WHERE i.id = #{itemId}
  AND p.id = #{participantId}
  AND r.settlement_id = #{settlementId}
